package net.officefloor.hq.app.payment;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.invoice.Invoice;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class PaymentService {

    private final PaymentRepository payments;
    private final InvoiceRepository invoices;
    private final Audit audit;

    public PaymentService(PaymentRepository payments, InvoiceRepository invoices, Audit audit) {
        this.payments = payments;
        this.invoices = invoices;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<PaymentResponse> list(Long projectId, Long invoiceId) {
        find(projectId, invoiceId);
        return payments.findByInvoiceIdOrderByDateAscIdAsc(invoiceId).stream().map(PaymentResponse::from).toList();
    }

    /**
     * Records a payment against an invoice that has been sent to the client and is still owing, and
     * works out the invoice's status from what has now been paid. A payment may not take the total
     * paid beyond the invoice amount.
     */
    @Transactional
    public PaymentResponse record(Long projectId, Long invoiceId, PaymentRequest request) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() == InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Send the invoice before recording a payment");
        }
        if (invoice.getStatus() == InvoiceStatus.VOID) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice has been cancelled");
        }
        if (!invoice.getStatus().isOwing()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The invoice is already paid");
        }
        BigDecimal paid = payments.sumAmountByInvoiceId(invoiceId).add(request.amount());
        if (paid.compareTo(invoice.getAmount()) > 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Payment is more than the balance due");
        }
        Payment saved = payments.saveAndFlush(new Payment(invoiceId, request.amount(), request.date()));
        invoice.applyPaidTotal(paid);
        invoices.flush();
        audit.record("PAYMENT_RECORDED id=" + saved.getId() + " amount=" + saved.getAmount().toPlainString());
        return PaymentResponse.from(saved);
    }

    private Invoice find(Long projectId, Long invoiceId) {
        return invoices.findById(invoiceId)
                .filter(i -> i.getProject().getId().equals(projectId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
    }
}
import { CurrencyPipe } from '@angular/common';
import { HttpErrorResponse } from '@angular/common/http';
import { Component, computed, inject, input, output, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { PaymentService } from './payment.service';

const TWO_DECIMALS = /^\d+(\.\d{1,2})?$/;

// The payments a client has made against an invoice, what is still owed, and a form to record
// another payment while the invoice is sent and not yet fully paid.
@Component({
  selector: 'app-invoice-payments',
  imports: [ReactiveFormsModule, CurrencyPipe],
  template: `
    <section aria-labelledby="invoice-payments-heading" data-testid="invoice-payments">
      <h2 id="invoice-payments-heading">Payments</h2>
      @if (payments.error()) {
        <p role="alert" data-testid="invoice-payments-error">Could not load the payments.</p>
      } @else if (payments.hasValue()) {
        @if (payments.value().length === 0) {
          <p data-testid="invoice-payments-empty">No payments recorded yet.</p>
        }
        <table data-testid="invoice-payments-table">
          <caption>What the client has paid on this invoice</caption>
          <thead>
            <tr>
              <th scope="col">Date</th>
              <th scope="col">Amount</th>
            </tr>
          </thead>
          <tbody>
            @for (p of payments.value(); track p.id) {
              <tr [attr.data-testid]="'payment-row-' + p.id">
                <td data-testid="payment-date">{{ p.date }}</td>
                <td data-testid="payment-amount">{{ p.amount | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
              </tr>
            }
          </tbody>
          <tfoot>
            <tr>
              <th scope="row">Paid</th>
              <td data-testid="invoice-paid-total">{{ paidCents() / 100 | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
            </tr>
            <tr>
              <th scope="row">Balance due</th>
              <td data-testid="invoice-balance-due">{{ balanceCents() / 100 | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
            </tr>
          </tfoot>
        </table>
      }

      @if (canRecord()) {
        <form [formGroup]="form" (ngSubmit)="submit()" data-testid="payment-form" novalidate>
          <h3>Record a payment</h3>
          <div>
            <label for="payment-amount">Amount</label>
            <input
              id="payment-amount"
              type="number"
              inputmode="decimal"
              min="0.01"
              step="0.01"
              formControlName="amount"
              data-testid="payment-form-amount"
              [attr.aria-invalid]="invalid('amount')"
              [attr.aria-describedby]="invalid('amount') ? 'payment-amount-error' : null"
            />
            @if (invalid('amount')) {
              <p id="payment-amount-error" role="alert" data-testid="payment-form-amount-error">
                Enter an amount greater than zero with at most two decimal places.
              </p>
            }
          </div>
          <div>
            <label for="payment-date">Date paid</label>
            <input
              id="payment-date"
              type="date"
              formControlName="date"
              data-testid="payment-form-date"
              [attr.aria-invalid]="invalid('date')"
              [attr.aria-describedby]="invalid('date') ? 'payment-date-error' : null"
            />
            @if (invalid('date')) {
              <p id="payment-date-error" role="alert" data-testid="payment-form-date-error">
                Enter the date the payment was made.
              </p>
            }
          </div>
          <button type="submit" data-testid="payment-form-submit" [disabled]="saving()">Record payment</button>
          @if (saveError()) {
            <p role="alert" data-testid="payment-form-error">{{ saveError() }}</p>
          }
        </form>
      }
    </section>
  `,
})
export class InvoicePayments {
  private readonly service = inject(PaymentService);

  readonly projectId = input.required<number>();
  readonly invoiceId = input.required<number>();
  /** The invoice total, which the payments count down. */
  readonly invoiceAmount = input.required<number>();
  /** Payments can be recorded once the invoice has been sent, until it is fully paid. */
  readonly canRecord = input.required<boolean>();
  /** Emits once a payment has been recorded, as it may change the invoice's status. */
  readonly recorded = output<void>();

  protected readonly payments = rxResource({
    params: () => ({ projectId: this.projectId(), invoiceId: this.invoiceId() }),
    stream: ({ params }) => this.service.list(params.projectId, params.invoiceId),
  });

  // Work in whole cents so the totals are exact.
  protected readonly paidCents = computed(() =>
    (this.payments.hasValue() ? this.payments.value() : []).reduce((sum, p) => sum + Math.round(p.amount * 100), 0),
  );
  protected readonly balanceCents = computed(() => Math.round(this.invoiceAmount() * 100) - this.paidCents());

  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    amount: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
    date: ['', [Validators.required]],
  });

  protected invalid(name: 'amount' | 'date'): boolean {
    const control = this.form.controls[name];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.saving.set(true);
    this.saveError.set(null);
    const { amount, date } = this.form.getRawValue();
    this.service.record(this.projectId(), this.invoiceId(), { amount: Number(amount), date }).subscribe({
      next: (created) => {
        this.payments.update((list) =>
          [...(list ?? []), created].sort((a, b) => a.date.localeCompare(b.date) || a.id - b.id),
        );
        this.form.reset();
        this.saving.set(false);
        this.recorded.emit();
      },
      error: (err: HttpErrorResponse) => {
        this.saveError.set(
          err.status === 409
            ? 'That payment is more than the balance due.'
            : 'Could not record the payment. Please try again.',
        );
        this.saving.set(false);
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** Money a client has paid against an invoice. */
export interface Payment {
  id: number;
  invoiceId: number;
  amount: number;
  /** ISO date (yyyy-MM-dd) the payment was made. */
  date: string;
}

export interface NewPayment {
  amount: number;
  date: string;
}

@Injectable({ providedIn: 'root' })
export class PaymentService {
  private readonly http = inject(HttpClient);

  /** An invoice's payments, oldest first. */
  list(projectId: number, invoiceId: number): Observable<Payment[]> {
    return this.http.get<Payment[]>(`/api/projects/${projectId}/invoices/${invoiceId}/payments`);
  }

  record(projectId: number, invoiceId: number, payment: NewPayment): Observable<Payment> {
    return this.http.post<Payment>(`/api/projects/${projectId}/invoices/${invoiceId}/payments`, payment);
  }
}
import { Component, computed, inject, input } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
